  `allow_view_record` tinyint(1) DEFAULT NULL COMMENT '允许查看接送记录',
  `allow_view_status` tinyint(1) DEFAULT NULL COMMENT '允许查看在校情况',
  `allow_growth_view` tinyint(1) DEFAULT NULL COMMENT '允许查看成长记录',
  `notify_on_pickup` tinyint(1) DEFAULT NULL COMMENT '接送消息通知',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_pickup_authorizations_deleted_at` (`deleted_at`) USING BTREE,
  KEY `idx_pickup_authorizations_student_id` (`student_id`) USING BTREE,
  KEY `idx_pickup_authorizations_review_status` (`review_status`) USING BTREE,
  CONSTRAINT `fk_pickup_authorizations_student` FOREIGN KEY (`student_id`) REFERENCES `students` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE `pickup_daily_designations` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
