CREATE TABLE `pickup_records` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  `kindergarten_id` bigint unsigned NOT NULL,
  `class_id` bigint unsigned NOT NULL,
  `student_id` bigint unsigned NOT NULL,
  `date` date NOT NULL,
  `type` tinyint NOT NULL COMMENT '1送入 2接走',
  `method` tinyint NOT NULL COMMENT '1扫码 2手动',
  `pickup_person_id` bigint unsigned DEFAULT NULL,
  `pickup_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `pickup_relation` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `operator_id` bigint unsigned DEFAULT NULL,
  `recorded_at` datetime(3) DEFAULT NULL,
  `is_abnormal` tinyint(1) DEFAULT '0',
  `abnormal_reason` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `remark` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `is_authorized_override` tinyint(1) DEFAULT '0',
  `override_name` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_pickup_records_deleted_at` (`deleted_at`) USING BTREE,
  KEY `idx_pickup_records_kindergarten_id` (`kindergarten_id`) USING BTREE,
  KEY `idx_pickup_records_class_id` (`class_id`) USING BTREE,
  KEY `idx_pickup_records_student_id` (`student_id`) USING BTREE,
  KEY `idx_pickup_records_date` (`date`) USING BTREE,
  KEY `fk_pickup_records_operator` (`operator_id`) USING BTREE,
  KEY `idx_pickup_records_pickup_person_id` (`pickup_person_id`),
  CONSTRAINT `fk_pickup_records_operator` FOREIGN KEY (`operator_id`) REFERENCES `users` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_pickup_records_student` FOREIGN KEY (`student_id`) REFERENCES `students` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE `point_accounts` (
